package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.LRUMap;
import java.io.*;
import java.lang.reflect.*;
import java.math.*;
import java.util.*;
import java.util.Map;
import java.util.Properties;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * Unit tests for TypeFactory._fromClass.
 * Since _fromClass is protected, we use a subclass or reflection to access it.
 * Here we use a Testable subclass to expose the method.
 */
public class TypeFactory__fromClass_TriageGen0Test {

    private TestableTypeFactory typeFactory;

    // Subclass to expose protected method for testing
    private static class TestableTypeFactory extends TypeFactory {
        protected TestableTypeFactory() {
            super(null, null);
        }

        @Override
        public JavaType _fromClass(ClassStack context, Class<?> rawType, TypeBindings bindings) {
            return super._fromClass(context, rawType, bindings);
        }
    }

    @Before
    public void setUp() {
        typeFactory = new TestableTypeFactory();
    }

    @Test
    public void testFromClass_WellKnownSimple() {
        // String is a well-known simple type
        JavaType result = typeFactory._fromClass(null, String.class, null);
        assertNotNull(result);
        assertEquals(String.class, result.getRawClass());
    }

    @Test
    public void testFromClass_CacheHit() {
        // First call to populate cache
        JavaType first = typeFactory._fromClass(null, Integer.class, null);
        // Second call should hit cache (cachable = true because bindings is null)
        JavaType second = typeFactory._fromClass(null, Integer.class, null);

        assertSame(first, second);
    }

    @Test
    public void testFromClass_RecursiveReference() {
        // Create a scenario where a class refers to itself via ClassStack
        // We simulate this by passing a context that already contains the rawType
        class SelfReferencingClass {}
        ClassStack context = new ClassStack(SelfReferencingClass.class);

        // The second call to context.find(SelfReferencingClass.class) will return the existing stack
        // triggering the ResolvedRecursiveType logic
        JavaType result = typeFactory._fromClass(context, SelfReferencingClass.class, null);

        assertTrue(result instanceof ResolvedRecursiveType);
        assertEquals(SelfReferencingClass.class, ((ResolvedRecursiveType) result).getRawClass());
    }

    @Test
    public void testFromClass_ArrayType() {
        // Test array resolution: String[]
        JavaType result = typeFactory._fromClass(null, String[].class, null);

        assertNotNull(result);
        assertTrue(result instanceof ArrayType);
        assertEquals(String.class, ((ArrayType) result).getElementType().getRawClass());
    }

    @Test
    public void testFromClass_PropertiesSpecialCase() {
        // Test the specific 'Properties.class' hack in the code
        JavaType result = typeFactory._fromClass(null, Properties.class, null);

        assertNotNull(result);
        assertTrue(result instanceof MapType);
        // Properties is expected to be Map<String, String> per the code logic
        assertEquals(String.class, ((MapType) result).getKeyType().getRawClass());
        assertEquals(String.class, ((MapType) result).getValueType().getRawClass());
    }

    @Test
    public void testFromClass_Interface() {
        // Test interface resolution (Map.class)
        JavaType result = typeFactory._fromClass(null, Map.class, null);

        assertNotNull(result);
        assertTrue(result.isInterface());
    }

    @Test
    public void testFromClass_WithBindings_NoCache() {
        // When bindings are NOT null, cachable = false. 
        // This forces the method to bypass the cache check and re-resolve.
        TypeBindings bindings = mock(TypeBindings.class);
        when(bindings.isEmpty()).thenReturn(false);

        JavaType result1 = typeFactory._fromClass(null, Integer.class, bindings);
        JavaType result2 = typeFactory._fromClass(null, Integer.class, bindings);

        assertNotNull(result1);
        assertNotNull(result2);
        // Since it's not cached, they might be different instances depending on _newSimpleType implementation,
        // but they should represent the same type.
        assertEquals(result1.getRawClass(), result2.getRawClass());
    }

    @Test
    public void testFromClass_SimpleClass() {
        // Test a standard class that isn't "well known" (using Object as a fallback)
        JavaType result = typeFactory._fromClass(null, Object.class, null);
        assertNotNull(result);
        assertEquals(Object.class, result.getRawClass());
    }
}
